s=s[:i]+'''function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const data: ListSessionsMessage = {type: 'list_sessions'};
  const {limit, before} = message;

  if (limit !== undefined) {
    if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0) {
      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
    }
    data.limit = limit;
  }

  if (before !== undefined) {
    const cursor = toSessionCursor(before);
    if (!cursor) {
      return {valid: false, error: 'list_sessions before must be {updatedAt, sessionId} naming a date and a session'};
    }
    data.before = cursor;
  }

  return {valid: true, data};
}

function toSessionCursor(value: unknown): SessionCursor | undefined {
  if (typeof value !== 'object' || value === null) return undefined;
  const {updatedAt, sessionId} = value as Record<string, unknown>;
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return undefined;
  if (!Number.isFinite(new Date(updatedAt).getTime())) return undefined;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH) return undefined;
  return {updatedAt, sessionId};
}
'''
